"""Build Batch 2 human-review document and labelled source/alpha/runtime proofs."""
import json,hashlib
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/assets/discraft-stamp-sweep/batch-2'
FONT=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',22)
def slug(m):return m.lower().replace(' ','-')
def tile(im):
 im=im.convert('RGBA');im.thumbnail((580,560));out=Image.new('RGBA',(600,580),'white');out.alpha_composite(im,((600-im.width)//2,(580-im.height)//2));return out.convert('RGB')
def main():
 rows=json.loads((OUT/'extraction.json').read_text());assignments=json.loads((ROOT/'source-data/stamp-manifest.json').read_text());checks=json.loads((OUT/'checks.json').read_text());assert len(rows)==31
 assert checks['validateData'] and checks['batchTests']==6 and checks['manifestTests']==10 and checks['nodeTests']==101
 verify=json.loads((OUT/'verification.json').read_text());assert verify['controlStampTexturesByteIdentical'] and verify['controlGeometryAndCameraIdentical']
 perf=json.loads((OUT/'perf-after.json').read_text());before=json.loads((OUT/'perf-before.json').read_text());assert perf['reps']=={'desktop':7,'phone':3};assert not any(r['failed'] for r in perf['summary'])
 placements=json.loads((OUT/'placement-verification.json').read_text());assert len(placements)==16
 total=sum(r['assetKB'] for r in rows if r['outcome']=='extracted')
 lines=['# Discraft stamp sweep — Batch 2','',f'**31 reviewed: 16 extracted · 12 fallback · 3 existing pilots retained. New production PNG payload: {total:.3f} KB.** Nuke remains fallback: its recorded G3T source has distinct blue and black inks; no single-ink flattening was made. All foil-risk outcomes are explicitly labelled below. No push or deployment.','', '| Mold | Source retailer actually used | Asset KB | Outcome |','| --- | --- | ---: | --- |']
 for r in rows:
  if r['outcome']=='control-unchanged':
   old=next(e for e in assignments if e['mold']==r['mold']);kb=(ROOT/'public'/old['asset']).stat().st_size/1000;retailer='Discraft (existing pilot)';outcome='Retained unchanged*'
  else:kb=r['assetKB'];retailer=r['sourceRetailer'];outcome='Extracted' if r['outcome']=='extracted' else 'Fallback — '+('two inks' if r['inkCountVerified']==2 else 'unverified ink count' if r['inkCountVerified'] is None else 'fidelity failed')
  lines.append(f"| {r['mold']} | {retailer} | {kb:.3f} | {outcome} |")
 lines+=['','*The expansion’s exact 31 `ready` rows include Buzzz, Zone and Luna. Their approved pilot designs/placements were preserved as required controls; alternate revisions were inspected but not extracted. Their existing KB are excluded from the new-payload total. `0.000 KB` on a fallback row means no new runtime asset, not an empty PNG.','','## Baseline and method','', 'First commit of this run: **`4005a8c`**, merging `origin/main` **`3abd397`** into the existing `codex/discraft-stamp-sweep` worktree after `472db6c`. Conflicts were mechanical: main’s mandatory scale schema + the existing 14 Batch 1 placements + the three pilot placements. `public/data.json` was regenerated through prepare; no hand edits. Batch 1 art and the completed fraction audit remain untouched.','', 'The ready-count gate returned exactly **31** before extraction. Every original’s decoded dimensions were checked against its recorded winning-source manifest. SHA-256 receipts are in [extraction.json](../assets/discraft-stamp-sweep/batch-2/extraction.json). Downloads remain local under ignored `outputs/discraft-batch2-sources/`; the committed crops are review evidence, never runtime photography.','', 'Ink count was reviewed per source before extraction. Distinct blue/black or pink/black imprints are not flattened. Ambiguous ink count is reported as unverified. Single metallic foils may vary in brightness/hue, but a source that cannot yield its complete design without plastic or missing fine marks is rejected. No redraw, tracing, generative repair, dilation, replacement lettering, or cross-mold elements.','', 'Per-mold channel classifiers retain original source pixels and arrangement. White RGB + alpha only. Each square uses the pilot’s circular-fit transparent padding. Full-disc diameter is the larger rim-to-rim centre-axis span on that same head-on source; stamp diameter is the complete nonzero source alpha’s larger width/height. `diameterFraction = sourceInkDiameterPx / sourceDiscDiameterPx`; `assetInkFraction = sourceInkDiameterPx / assetSquarePx`. No flight-plate denominator or 6.2 cm cap.','', 'Marshall Street’s tinted tabletop requires measured edge transitions rather than a white-background chroma test: median 5px centre bands, inspected outer-rim edges. Joy’s bottom tabletop seam is excluded. Reaper’s white backdrop uses the full outer centre-axis silhouette. Measurement proofs mark disc bounds cyan and ink bounds red. All assignments pass the existing full-disc renderer’s fraction/mesh checks without renderer changes.','', 'Wiring stays source manifest → `prepare_data.py` → `validate_data.py`. Alternate provenance now requires the exact reviewed own-mold ID/page/image/retailer/hash tuple, as well as the existing Discraft/rights/path/placement checks. Atlas markers and lazy loading are unchanged.','','## Verification','', 'Fresh data validation: **33 assigned stamps, 2,434 identities, 1,182 flight matches, 0 local photos**. Manifest tests **10/10**; Batch 2 invariants **6/6**; geometry/atlas/bag/collection/photo Node regressions **101/101**. Existing 17 assignment objects and all their PNG bytes equal the post-merge baseline; meta, record ordering and all non-stamp catalog fields are identical. The 8 risky and 48 no entries, rejected GT/Banger Top and all Batch 1 sweep objects remain unchanged.','', 'The dedicated pixel proof uses deterministic SwiftShader WebGL after native D3D11 returned small raster/compositor differences on unchanged controls. It runs the same production modules, shaders, masks and poses. Separate placement, existing viewer/pop-out/bag/photo browser suites and the unmodified performance gate use native D3D11. Browser proof suite checks all 16 new viewer textures, own-mold assignments and pulled bag/storage changes; every pilot and Batch 1 control; Nuke, still-no Archer and non-Discraft Destroyer; all other Batch 2 fallbacks; unchanged photo/clay precedence and thumbnails; cancellation/failure fallback, brand gate and zero atlas stamp requests. Texture, geometry and camera controls are exact. Viewer controls require byte-identical production frames, textures, geometry and camera; bag presentation retains the original one-level / 0.01% quantization bound. Browser-composited viewer screenshot deltas are recorded separately with a maximum one-channel-level bound: the prior 0.01% changed-pixel fraction proved unstable despite identical production frames. No production renderer or perf margin changed. [Browser receipt](../assets/discraft-stamp-sweep/batch-2/verification.json). Native thumbnail verification independently shows **16 new designs / 20 unchanged controls** and zero atlas stamp requests before selection: [receipt](../assets/discraft-stamp-sweep/batch-2/native-thumbnails.json), [comparison](../assets/discraft-stamp-sweep/batch-2/native-thumbnails.png).','', checks['browserNotes'],'', 'Other browser suites: '+', '.join(checks['browserSuites'])+'. '+checks['suiteNotes'],'', 'Independent review found and corrected Ares arc, Raptor final R/champion line, Stalker first S, and a newly admitted Ares plastic fragment. Independent source-coordinate pixel regressions preserve the edge elements and reject the fragment. Exact alternate-source validation was hardened after a deliberately wrong page/missing image/hash test first failed. Final read-only recheck: no remaining important findings.','','## Performance — unchanged default gate','', f"Both baseline and final pass at **7 desktop / 3 phone warm repetitions**, original **1.15×**, **1.5 / 3 ms** slack and **+1 long task**, including aggregate and paired checks. Baseline {before['elapsedSeconds']:.2f}s; final {perf['elapsedSeconds']:.2f}s. No PERF_REPS or margin override. No quiet failure discarded. Raw [before](../assets/discraft-stamp-sweep/batch-2/perf-before.json) / [after](../assets/discraft-stamp-sweep/batch-2/perf-after.json).",'', '| Device / metric | Baseline 2D | Baseline 3D | Final 2D | Final 3D | 3D delta | Final limit | Paired excess |','| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
 for p in perf['summary']:
  b=next(r for r in before['summary'] if r['device']==p['device'] and r['metric']==p['metric']);lines.append(f"| {p['device']} {p['metric']} | {b['2D median']:.3f} | {b['3D median']:.3f} | {p['2D median']:.3f} | {p['3D median']:.3f} | {p['3D median']-b['3D median']:+.3f} | {p['limit']:.3f} | {p['paired median excess']:.3f} |")
 lines+=['',checks['perfNotes'],'', 'The following proof sections are the local fidelity verdicts. Freddy’s visual judgment remains available for every labelled foil-risk section; no human approval is claimed.']
 ordered=sorted(rows,key=lambda r:(r['mold']!='Nuke',rows.index(r)))
 for r in ordered:
  mold=r['mold'];name=slug(mold);flag=' — FOIL-RISK' if 'foil-risk' in r['flags'] else '';dedicated=' — DEDICATED NUKE HOLDOUT' if mold=='Nuke' else ''
  lines+=['',f"## {mold}{dedicated}{flag} — {r['outcome'].upper()}",'',f"Recorded alternate: **{r['sourceRetailer']}**, [page]({r['sourceURL']}) · [original]({r['sourceImageURL']}); verified {r['sourceSize'][0]}×{r['sourceSize'][1]} px. Source SHA-256 `{r['sourceSHA256']}`.",'']
  source=Image.open(ROOT/'outputs/discraft-batch2-sources'/(name+'.source')).convert('RGB')
  if r['outcome']=='control-unchanged':
   e=next(e for e in assignments if e['mold']==mold);source=Image.open(ROOT/'source-data/stamp-sources'/(name+'.png')).convert('RGB');alpha=Image.open(ROOT/'public'/e['asset']);label='Retained official pilot alpha';actual=f"Actual retained provenance: **Discraft**, [approved pilot page]({e['sourceURL']}). Alternate revision above was not transferred. Existing placement {e['placement']['diameterFraction']:.6%}; asset {(ROOT/'public'/e['asset']).stat().st_size/1000:.3f} KB, unchanged."
  elif r['outcome']=='extracted':
   box=r['sourceInkBounds'];pad=24;detail=source.crop((max(0,box[0]-pad),max(0,box[1]-pad),min(source.width,box[2]+pad),min(source.height,box[3]+pad)));detail.thumbnail((1300,1300));detail.save(OUT/(name+'-ink-detail.jpg'),quality=95);axes=r['sourceCentreAxes'];source=source.crop((max(0,axes[0][0]-12),max(0,axes[1][0]-12),min(source.width,axes[0][1]+12),min(source.height,axes[1][1]+12)));alpha=Image.open(ROOT/'public'/r['asset']);label='Accepted own-source alpha';actual=f"**One ink verified. {r['assetKB']:.3f} KB.** Full disc {r['sourceDiscDiameterPx']} px; complete ink {r['sourceInkDiameterPx']} px; target **{r['placement']['diameterFraction']:.6%}** of full disc. Asset square {r['assetSize'][0]} px; ink/asset {r['placement']['assetInkFraction']:.6%}. Source ink bounds `{r['sourceInkBounds']}`; source centre axes `{r['sourceCentreAxes']}`. Native renderer physical fraction {next(p['physicalInkFraction'] for p in placements if p['mold']==mold):.6%} (within 0.0002 percentage points)."
  else:
   alpha=Image.open(OUT/(name+'-candidate.png')) if (OUT/(name+'-candidate.png')).exists() else None;label='REJECTED trial: never assigned' if alpha else 'No alpha: extraction stopped';count='unverified' if r['inkCountVerified'] is None else str(r['inkCountVerified']);actual=f"**Fallback retained. Ink count: {count}. New asset: 0.000 KB; no placement assigned.** {r['reason']}"
  source.thumbnail((1300,1300));source.save(OUT/(name+'-source-crop.jpg'),quality=95)
  board=Image.new('RGB',(1800,660),'#d9dfe5');d=ImageDraw.Draw(board)
  for i,text in enumerate(['Own source crop' if r['outcome']!='control-unchanged' else 'Approved official pilot source',label,'Tinted production viewer' if r['outcome']=='extracted' else 'Retained production render']):d.text((i*600+14,14),text,fill='#12161c',font=FONT)
  board.paste(tile(source),(0,65))
  if alpha:
   a=alpha.getchannel('A');paint=Image.new('RGBA',alpha.size,'#12161c');paint.putalpha(a);board.paste(tile(paint),(600,65))
  else:d.multiline_text((630,250),'No single-ink extraction accepted.\nNo flattened stamp is assigned.',fill='#12161c',font=FONT,spacing=12)
  board.paste(tile(Image.open(OUT/('after-'+name+'-viewer.png'))),(1200,65));board.save(OUT/('proof-'+name+'.jpg'),quality=95)
  if r['outcome']=='control-unchanged':lines+=['',f"![{mold} inspected alternate revision — not extracted](../assets/discraft-stamp-sweep/batch-2/{name}-source.jpg)",'']
  lines+=[actual,'',f"![{mold}: source, extraction verdict, tinted in-context render](../assets/discraft-stamp-sweep/batch-2/proof-{name}.jpg)",'',f"[Source crop](../assets/discraft-stamp-sweep/batch-2/{name}-source-crop.jpg) · [Production viewer](../assets/discraft-stamp-sweep/batch-2/after-{name}-viewer.png)"]
  if r['outcome']=='extracted':lines+=['',f"![{mold} on white, black and saturated blue](../assets/discraft-stamp-sweep/batch-2/{name}-backgrounds.png)",'',f"[Measurement bounds](../assets/discraft-stamp-sweep/batch-2/{name}-measurement.jpg) · [Source ink detail](../assets/discraft-stamp-sweep/batch-2/{name}-ink-detail.jpg) · [Alpha PNG](../../public/{r['asset']})"]
  elif alpha and r['outcome']=='fallback':lines+=['',f"**Rejected trial only — never shipped.** The missing-detail/plastic problem is visible below; its alpha is not a runtime asset.",'',f"![{mold} rejected foil trial on three backgrounds](../assets/discraft-stamp-sweep/batch-2/{name}-backgrounds.png)"]
 (ROOT/'docs/discraft-stamp-sweep/batch-2.md').write_text('\n'.join(lines)+'\n',encoding='utf8');print('31 proof sections; new asset KB:',round(total,3))
if __name__=='__main__':main()
